import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Agent 架构与工具调用","description":"理解 ReAct 循环、工具定义、记忆管理与失败模式，判断什么任务适合交给 Agent，什么任务不该。","frontmatter":{"title":"Agent 架构与工具调用","description":"理解 ReAct 循环、工具定义、记忆管理与失败模式，判断什么任务适合交给 Agent，什么任务不该。"},"headers":[],"relativePath":"ai/agent-architecture.md","filePath":"ai/agent-architecture.md","lastUpdated":1786263069000}'),e={name:"ai/agent-architecture.md"};function l(h,t,p,r,d,o){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="agent-架构与工具调用" tabindex="-1">Agent 架构与工具调用 <a class="header-anchor" href="#agent-架构与工具调用" aria-label="Permalink to &quot;Agent 架构与工具调用&quot;">​</a></h1><p>LLM 单独使用时，它只能&quot;根据输入直接生成输出&quot;，不会查资料、不会算账、不会执行代码。Agent 的核心思想是给模型加上一个能力：在生成过程中调用外部工具，把工具返回的结果再喂回上下文，继续推理。这样模型擅长的事情（理解、规划、生成）由它做，它不擅长的事情（精确计算、检索、查询接口）交给确定性代码。</p><h2 id="react-思考—行动—观察的循环" tabindex="-1">ReAct：思考—行动—观察的循环 <a class="header-anchor" href="#react-思考—行动—观察的循环" aria-label="Permalink to &quot;ReAct：思考—行动—观察的循环&quot;">​</a></h2><p>大多数 Agent 都遵循 ReAct 模式，即&quot;推理（Reason）+ 行动（Act）&quot;交替进行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>思考: 用户要查上个月的销冠，我需要先查询销售数据库。</span></span>
<span class="line"><span>行动: 调用 querySales(month=&quot;上月&quot;, sort=&quot;desc&quot;, limit=1)</span></span>
<span class="line"><span>观察: { &quot;name&quot;: &quot;张三&quot;, &quot;amount&quot;: 128000 }</span></span>
<span class="line"><span>思考: 拿到了结果，可以回答用户了。</span></span>
<span class="line"><span>回答: 上个月销冠是张三，销售额 12.8 万。</span></span></code></pre></div><p>这个循环由三个部分组成：</p><table tabindex="0"><thead><tr><th>环节</th><th>谁来做</th><th>内容</th></tr></thead><tbody><tr><td>思考</td><td>模型</td><td>决定下一步做什么、调用哪个工具</td></tr><tr><td>行动</td><td>框架/代码</td><td>执行模型选定的工具，拿到结果</td></tr><tr><td>观察</td><td>框架/代码</td><td>把工具结果放进上下文，交还模型</td></tr></tbody></table><p>循环需要一个终止条件：模型判断&quot;已经能回答了&quot;就输出最终答案；或者达到最大步数上限，强制停止。没有步数上限的 Agent 可能陷入无限循环，持续消耗 Token。</p><h2 id="工具定义-函数调用" tabindex="-1">工具定义：函数调用 <a class="header-anchor" href="#工具定义-函数调用" aria-label="Permalink to &quot;工具定义：函数调用&quot;">​</a></h2><p>工具本质是一个有明确入参和返回值的函数，模型不需要看它的实现，只需要看它的&quot;说明书&quot;：名字、用途、参数 schema。主流模型都支持结构化的函数调用（function calling），模型按 schema 输出参数，框架负责真正执行。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;queryOrder&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;按订单号查询订单状态和金额&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;parameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;object&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;orderId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;订单编号，如 ORD12345&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orderId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>定义工具有几个实践要点：</p><ul><li><strong>description 要写给模型看</strong>：说清什么时候该用、什么时候不该用。模型是根据 description 决定是否调用的，写不清楚就会乱调或漏调。</li><li><strong>参数要简单且可校验</strong>：能用枚举就用枚举，尽量让模型少出错。</li><li><strong>返回结构要稳定</strong>：工具返回的 JSON 结构要固定，方便模型解读，也方便程序兜底。</li><li><strong>工具要够少</strong>：给模型几十个工具，它选错的概率会上升。按场景拆分工具集，而不是一次全塞给它。</li></ul><h2 id="记忆与上下文管理" tabindex="-1">记忆与上下文管理 <a class="header-anchor" href="#记忆与上下文管理" aria-label="Permalink to &quot;记忆与上下文管理&quot;">​</a></h2><p>Agent 跑起来后，上下文会不断增长：系统指令、历史对话、每一次思考、每一次工具调用结果，全都会累积。一旦超出窗口，就会丢失关键信息或直接报错。</p><p>常见的处理策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适用</th></tr></thead><tbody><tr><td>滑动窗口</td><td>只保留最近 N 轮</td><td>短对话、无状态任务</td></tr><tr><td>摘要压缩</td><td>把早期对话总结成摘要</td><td>长对话、需要保留主旨</td></tr><tr><td>外部记忆</td><td>把历史存到数据库，按需检索</td><td>需要长期记忆的助手</td></tr></tbody></table><p>不要把&quot;全量历史&quot;无脑塞进上下文。很多任务只需要当前这一步的相关信息，过多的历史反而让模型分心，还增加成本。</p><h2 id="何时该用、何时不该用-agent" tabindex="-1">何时该用、何时不该用 Agent <a class="header-anchor" href="#何时该用、何时不该用-agent" aria-label="Permalink to &quot;何时该用、何时不该用 Agent&quot;">​</a></h2><p>Agent 不是万能的，它的代价是：不可控、慢、贵、难调试。判断标准是——这个任务是否真的需要&quot;动态决定下一步做什么&quot;。</p><table tabindex="0"><thead><tr><th>适合 Agent</th><th>不适合 Agent</th></tr></thead><tbody><tr><td>步骤无法预先确定，要根据中间结果分支</td><td>步骤固定，只是串起来执行</td></tr><tr><td>需要理解自然语言意图再选工具</td><td>输入结构固定，分支明确</td></tr><tr><td>任务开放式，可能需要多轮探索</td><td>简单的数据提取或转换</td></tr></tbody></table><p>很多看起来&quot;需要 Agent&quot;的场景，其实用一个固定流水线（先检索 → 再让模型总结）就够了。固定流水线可控、可测、便宜；Agent 应该作为&quot;当流水线不够用时&quot;的升级，而不是默认选择。</p><h2 id="失败模式" tabindex="-1">失败模式 <a class="header-anchor" href="#失败模式" aria-label="Permalink to &quot;失败模式&quot;">​</a></h2><p>Agent 会以几种典型方式失败，设计时要提前考虑：</p><ul><li><strong>循环调用</strong>：反复调用同一个工具却拿不到想要的结果，空转直到步数上限。需要检测重复调用并强制终止。</li><li><strong>幻觉工具调用</strong>：模型编造一个不存在的工具，或给真实工具填了不合法的参数。框架必须校验工具名和参数，校验失败要反馈给模型而不是直接报错。</li><li><strong>过度行动</strong>：本该先确认就执行了有副作用的操作（发邮件、删数据）。有副作用的动作必须有人工确认或独立权限层。</li><li><strong>上下文污染</strong>：工具返回的结果里夹带了注入指令，影响模型后续判断。工具返回也应当作不可信数据处理。</li></ul><h2 id="务实的设计清单" tabindex="-1">务实的设计清单 <a class="header-anchor" href="#务实的设计清单" aria-label="Permalink to &quot;务实的设计清单&quot;">​</a></h2><ul><li>是否设定了最大步数和重复调用检测？</li><li>每个工具的 description 是否说清了使用时机？</li><li>有副作用的工具是否有人工确认或权限校验？</li><li>上下文是否会无限增长，有没有压缩或清理策略？</li><li>这个任务是否真的需要 Agent，还是固定流水线就够？</li></ul><p>Agent 的价值在于把模型的&quot;理解与规划&quot;能力和外部系统的&quot;确定性执行&quot;能力组合起来。把它用在真正需要灵活性的地方，其余地方用更简单可控的方式，整体系统才会稳。</p>`,28)])])}const g=s(e,[["render",l]]);export{u as __pageData,g as default};
